function nav(current='') {
  const links = [['Home','/'],['Services','/services'],['Work','/work'],['Solutions','/solutions'],['Process','/process'],['About','/about'],['Insights','/insights']];
  return `<header class="nav"><div class="container nav-inner"><a class="brand" href="/"><span class="brand-mark">N</span><span>NEXORA WEB</span></a><nav class="menu" aria-label="Primary navigation">${links.map(([label,href]) => `<a class="${current===href?'active':''}" href="${href}">${label}</a>`).join('')}</nav><div class="nav-actions"><a class="btn" href="/contact">Talk to us</a><a class="btn btn-primary" href="/start-project">Start a project ↗</a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false">☰</button></div></div></header>`;
}
function footer() {
  return `<footer class="footer"><div class="container"><div class="footer-top"><div><a class="brand" href="/"><span class="brand-mark">N</span><span>NEXORA WEB</span></a><p class="muted" style="max-width:360px;margin:18px 0 0">Premium websites, digital products and growth systems for businesses that want to move with intention.</p><div style="margin-top:24px"><span class="eyebrow">Made by Nexora Web</span></div></div><div><h4>Explore</h4><a href="/services">Services</a><a href="/work">Work</a><a href="/solutions">Solutions</a><a href="/process">Process</a></div><div><h4>Company</h4><a href="/about">About</a><a href="/insights">Insights</a><a href="/contact">Contact</a><a href="/start-project">Start a project</a><a href="/admin">Admin</a></div><div><h4>Capabilities</h4><a href="/services/web-design">Web design</a><a href="/services/development">Development</a><a href="/services/commerce">E-commerce</a><a href="/services/growth">Digital growth</a></div></div><div class="footer-bottom"><span>© 2026 Nexora Web. All rights reserved.</span><span><a href="/privacy">Privacy</a> · <a href="/terms">Terms</a></span></div></div></footer>`;
}
function layout({title, description, current, content, canonicalPath='/'}) {
  const canonical = canonicalPath;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><meta name="description" content="${description}"><link rel="canonical" href="${canonical}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><meta property="og:site_name" content="Nexora Web"><meta property="og:title" content="${title}"><meta property="og:description" content="${description}"><meta property="og:type" content="website"><meta property="og:image" content="/og-image.svg"><meta name="theme-color" content="#5b2cff"><script type="application/ld+json">${JSON.stringify({"@context":"https://schema.org","@type":"Organization","name":"Nexora Web","url":"/","description":description})}</script><style>${css}</style></head><body><div class="grid-paper"></div>${nav(current)}<main>${content}</main>${footer()}<script>${clientJs}</script></body></html>`;
}

const clientJs = "(() => {\nconst nav=document.querySelector('.nav'), toggle=document.querySelector('.menu-toggle');\nif(toggle) toggle.addEventListener('click',()=>{nav.classList.toggle('open');toggle.setAttribute('aria-expanded',nav.classList.contains('open'))});\nconst io=typeof IntersectionObserver!=='undefined'?new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add('in')),{threshold:.12}):null;document.querySelectorAll('.reveal').forEach(e=>io?io.observe(e):e.classList.add('in'));\nconst projectForm=document.querySelector('#project-form');\nif(projectForm){let step=0;const panes=[...projectForm.querySelectorAll('[data-step]')],progress=projectForm.querySelector('.progress span'),label=projectForm.querySelector('[data-step-label]');const render=()=>{panes.forEach((p,i)=>p.hidden=i!==step);if(progress)progress.style.width=((step+1)/panes.length*100)+'%';if(label)label.textContent=(step+1)+' / '+panes.length};render();projectForm.querySelectorAll('[data-next]').forEach(b=>b.addEventListener('click',()=>{const pane=panes[step],inputs=[...pane.querySelectorAll('input,select,textarea')];if(!inputs.every(i=>i.checkValidity())){pane.querySelector('input:invalid,select:invalid,textarea:invalid')?.focus();return}if(step<panes.length-1){step++;render()}}));projectForm.querySelectorAll('[data-prev]').forEach(b=>b.addEventListener('click',()=>{if(step>0){step--;render()}}));projectForm.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(projectForm)),notice=projectForm.querySelector('.notice');try{const r=await fetch('/api/projects',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Could not submit');notice.textContent='Project brief received. We will follow up using the contact details you provided.';notice.className='notice success show';projectForm.reset();step=0;render()}catch(err){notice.textContent=err.message;notice.className='notice error show'}})}\nconst contact=document.querySelector('#contact-form');if(contact)contact.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(contact)),n=contact.querySelector('.notice');try{const r=await fetch('/api/contact',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Unable to send');n.textContent='Thanks. Your message is in the Nexora inbox queue.';n.className='notice success show';contact.reset()}catch(err){n.textContent=err.message;n.className='notice error show'}});\nconst newsletter=document.querySelector('#newsletter-form');if(newsletter)newsletter.addEventListener('submit',async e=>{e.preventDefault();const email=new FormData(newsletter).get('email'),n=newsletter.querySelector('.notice');try{const r=await fetch('/api/newsletter',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Unable to subscribe');n.textContent='You’re on the list.';n.className='notice success show';newsletter.reset()}catch(err){n.textContent=err.message;n.className='notice error show'}});\nconst WORK_KEY='nexora.customWork.v1';const esc=s=>String(s??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m]));const loadWork=()=>{try{const x=JSON.parse(localStorage.getItem(WORK_KEY)||'[]');return Array.isArray(x)?x:[]}catch{return[]}};const saveWork=x=>localStorage.setItem(WORK_KEY,JSON.stringify(x));\nconst card=p=>'<article class=\"design-card\"><div class=\"design-thumb\">'+(p.image?'<img src=\"'+esc(p.image)+'\" alt=\"'+esc(p.title||'Website design')+'\" loading=\"lazy\">':'<div class=\"design-placeholder\">Nexora Design</div>')+'</div><div class=\"design-body\"><div class=\"eyebrow\">'+esc(p.category||'Website design')+'</div><h3>'+esc(p.title||'Untitled project')+'</h3><p>'+esc(p.description||'')+'</p><div class=\"tags\">'+(p.tags||[]).slice(0,6).map(t=>'<span class=\"tag\">'+esc(t)+'</span>').join('')+'</div><div class=\"design-actions\">'+(p.url?'<a class=\"btn btn-primary\" href=\"'+esc(p.url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">View website ↗</a>':'')+'</div></div></article>';\nconst customShell=document.querySelector('#custom-work-shell'),customGrid=document.querySelector('#custom-work-grid');if(customGrid){const items=loadWork();if(items.length){customGrid.innerHTML=items.map(card).join('');if(customShell)customShell.hidden=false;}}\nconst manager=document.querySelector('#work-manager');if(manager){const form=manager.querySelector('#design-form'),file=manager.querySelector('#design-image'),preview=manager.querySelector('#image-preview'),imageData=manager.querySelector('#image-data'),fileName=manager.querySelector('.file-name'),list=manager.querySelector('#manager-list'),notice=manager.querySelector('.notice');const showList=()=>{const items=loadWork();list.innerHTML=items.length?items.map(p=>'<div class=\"manager-item\"><div class=\"thumb\">'+(p.image?'<img src=\"'+esc(p.image)+'\" alt=\"\">':'')+'</div><div class=\"meta\"><strong>'+esc(p.title)+'</strong><span>'+esc(p.category||'Website design')+'</span></div><button class=\"btn danger-btn\" type=\"button\" data-delete-work=\"'+esc(p.id)+'\">Delete</button></div>').join(''):'<div class=\"manager-empty\">No designs added yet.</div>';};if(file)file.addEventListener('change',()=>{const f=file.files?.[0];if(!f)return;fileName.textContent=f.name;const reader=new FileReader();reader.onload=()=>{imageData.value=reader.result;preview.hidden=false;preview.querySelector('img').src=reader.result};reader.readAsDataURL(f);});manager.addEventListener('click',e=>{const btn=e.target.closest('[data-delete-work]');if(btn){const id=btn.getAttribute('data-delete-work');saveWork(loadWork().filter(x=>String(x.id)!==String(id)));showList();}});form.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(form),title=String(fd.get('title')||'').trim(),category=String(fd.get('category')||'Website design').trim(),description=String(fd.get('description')||'').trim(),url=String(fd.get('url')||'').trim(),tags=String(fd.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,6),image=String(imageData.value||'');if(!title||!description){notice.textContent='Title and description are required.';notice.className='notice error show';return}if(url&&!/^https?:\\/\\//i.test(url)){notice.textContent='Website URL must start with http:// or https://';notice.className='notice error show';return}const item={id:(crypto.randomUUID?crypto.randomUUID():String(Date.now())),title,category,description,url,tags,image,createdAt:new Date().toISOString()};saveWork([item,...loadWork()]);form.reset();imageData.value='';preview.hidden=true;fileName.textContent='';notice.textContent='Design added to your work library on this browser.';notice.className='notice success show';showList();});manager.querySelectorAll('[data-export-work]').forEach(btn=>btn.addEventListener('click',()=>{const blob=new Blob([JSON.stringify(loadWork(),null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nexora-work-library.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}));const importer=manager.querySelector('#import-work');if(importer)importer.addEventListener('change',()=>{const f=importer.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!Array.isArray(data))throw new Error('Invalid file');saveWork(data);showList();notice.textContent='Work library imported successfully.';notice.className='notice success show'}catch{notice.textContent='Import failed. Please choose a Nexora JSON export.';notice.className='notice error show'}};reader.readAsText(f);});showList();}\n})();";

function renderHome() {
  return layout({title:'Nexora Web — Premium Digital Partner',description:'Premium websites, digital products and growth systems for ambitious businesses.',current:'/',content:`
  <section class="hero"><div class="container hero-grid"><div class="reveal"><div class="eyebrow">Digital partner for ambitious businesses</div><h1>Build digital.<br><span>Make it matter.</span></h1><p class="hero-copy">Nexora Web creates premium websites, digital products and conversion systems that turn business strategy into a sharper online presence.</p><div class="hero-actions"><a class="btn btn-primary" href="/start-project">Start a project ↗</a><a class="btn" href="/work">Explore our work</a></div><div class="hero-meta"><div class="stat"><strong>12+</strong><small>Launches delivered</small></div><div class="stat"><strong>6</strong><small>Core capabilities</small></div><div class="stat"><strong>100%</strong><small>Responsive by default</small></div></div></div><div class="hero-art reveal"><div class="orb"></div><div class="float-card one"><span class="mini">Current focus</span><strong>Brand → Build</strong><span class="muted">One connected digital system</span></div><div class="float-card two"><span class="mini">Typical outcome</span><strong>Sharper + Faster</strong><span class="muted">Built around conversion</span></div></div></div></section>
  <section class="strip"><div class="container strip-row">${['NORTHSTAR','ORBITAL','ARCONE','VERDE','KINETIQ','LUMEN'].map(x=>`<span>${x}</span>`).join('')}</div></section>
  <section class="section"><div class="container"><div class="section-head reveal"><div><div class="eyebrow">What we do</div><h2>Strategy, design and engineering in one team.</h2></div><p>One connected system from the first strategic question to the final interaction.</p></div><div class="cards three">${services.slice(0,3).map(s=>`<article class="card reveal"><div class="card-number">${s.number} / ${s.label}</div><h3>${s.title}</h3><p>${s.description}</p><a class="card-link" href="/services/${s.slug}">Explore ${s.title} ↗</a></article>`).join('')}</div></div></section>
  <section class="section tight"><div class="container"><div class="section-head reveal"><div><div class="eyebrow">Selected work</div><h2>Built to be noticed. Designed to perform.</h2></div><a class="btn" href="/work">View all projects ↗</a></div><div class="work-grid"><a class="project large reveal" href="/work/orbit-health"><div class="project-visual violet"></div><div class="project-content"><div class="eyebrow">Orbit Health / ${projects[0].category}</div><h3>${projects[0].title}</h3><div class="tags">${projects[0].tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div></div></a><div style="display:grid;gap:18px">${projects.slice(1).map(p=>`<a class="project small reveal" href="/work/${p.slug}"><div class="project-visual ${p.tone}"></div><div class="project-content"><div class="eyebrow">${p.client} / ${p.category}</div><h3>${p.title}</h3><div class="tags">${p.tags.slice(0,2).map(t=>`<span class="tag">${t}</span>`).join('')}</div></div></a>`).join('')}</div></div></div></section>
  <section class="section dark"><div class="container steps"><div class="reveal"><div class="eyebrow">How we work</div><h2 style="font-size:clamp(2.4rem,4.4vw,4.8rem);line-height:.98;letter-spacing:-.07em;margin:12px 0 18px">From first question to final pixel, with intent.</h2><p class="muted">A focused process keeps the work moving without losing the details that make the final product feel considered.</p><a class="btn btn-primary" style="margin-top:22px" href="/process">See our process ↗</a></div><div>${[['01','Discover','Business goals, audience, constraints and the real problem to solve.'],['02','Define','Content architecture, journeys, creative direction and success measures.'],['03','Design','A visual system with hierarchy, rhythm, contrast and personality.'],['04','Build','Responsive implementation, performance, accessibility and polish.']].map(([n,t,p])=>`<div class="step reveal"><div class="num">${n}</div><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></div></section>
  <section class="section"><div class="container split"><div class="reveal"><div class="eyebrow">A better digital standard</div><p style="font-size:clamp(1.9rem,3.2vw,3.2rem);line-height:1.08;letter-spacing:-.045em;margin:12px 0 24px">“We care about the moment someone lands on a page—and the reason they decide to stay.”</p><strong>Nexora Web</strong><div class="muted">Design + engineering partner</div></div><div class="metrics reveal"><div class="metric"><strong>01</strong><span>Connected team</span></div><div class="metric"><strong>06</strong><span>Service lines</span></div><div class="metric"><strong>04</strong><span>Core process stages</span></div><div class="metric"><strong>24/7</strong><span>Digital presence</span></div></div></div></section>
  <section class="section dark"><div class="container center reveal"><div class="eyebrow">Have a good problem?</div><h2 style="font-size:clamp(2.8rem,6vw,6.2rem);line-height:.94;letter-spacing:-.07em;max-width:950px;margin:14px auto 20px">Let’s make the next version feel inevitable.</h2><p class="muted" style="max-width:650px;margin:0 auto">Tell us what you are trying to change, launch or improve.</p><a class="btn btn-primary" style="margin-top:25px" href="/start-project">Start a project ↗</a></div></section>`});
}

function renderListing({kind,current,title,description}) {
  const items = kind==='services' ? services.map(s=>({href:'/services/'+s.slug,eyebrow:s.number+' / '+s.label,title:s.title,description:s.description})) : kind==='solutions' ? solutions.map(s=>({href:'/solutions/'+s.slug,eyebrow:'Solution',title:s.title,description:s.description})) : insights.map(i=>({href:'/insights/'+i.slug,eyebrow:i.category,title:i.title,description:i.excerpt}));
  return layout({title,description,current,content:`<section class="page-hero"><div class="container"><div class="eyebrow">Nexora / ${kind}</div><h1>${title.split(' — ')[0]}</h1><p>${description}</p></div></section><section class="section"><div class="container"><div class="cards three">${items.map(x=>`<a class="card reveal" href="${x.href}"><div class="eyebrow">${x.eyebrow}</div><h3 style="font-size:1.5rem">${x.title}</h3><p>${x.description}</p><span class="card-link">Explore ↗</span></a>`).join('')}</div></div></section>`});
}
