  return layout({title:'Selected work — Nexora Web',description:'Explore selected Nexora Web case studies and your own website designs.',current:'/work',content:'<section class="page-hero"><div class="container"><div class="eyebrow">Selected work</div><h1>Work that makes the business case visible.</h1><p>Explore Nexora case studies, then add your own website designs to build a personal work library.</p><div class="work-toolbar"><div class="work-toolbar-copy"><strong>Your design library</strong><p>Add screenshots or design previews, give each project context, and optionally link the live website.</p></div><a class="btn btn-primary" href="/work-manager">Add your design ↗</a></div></div></section><section class="section"><div class="container"><div id="custom-work-shell" class="custom-work-shell" hidden><div class="section-head"><div><div class="eyebrow">Your work</div><h2>Website designs you added.</h2></div><a class="btn" href="/work-manager">Manage designs ↗</a></div><div id="custom-work-grid" class="cards three"></div></div><div style="margin-top:34px"><div class="section-head"><div><div class="eyebrow">Nexora work</div><h2>Selected projects from the studio.</h2></div></div><div class="cards three">'+customCards+'</div></div></div></section>'});
