function renderWorkManager() {
  return layout({title:'Admin — Nexora Web',description:'Manage your Nexora Web portfolio designs.',current:'/work',content:'<section class="page-hero"><div class="container"><div class="eyebrow">Admin / Work library</div><h1>Manage your website designs.</h1><p>Add a preview image, project details and an optional live URL. Your saved designs appear inside Explore Our Work on this browser.</p></div></section><section class="section"><div class="container" id="work-manager"><div class="manager-shell"><form id="design-form" class="manager-card reveal"><div class="eyebrow">Add design</div><h2>New project</h2><p class="helper">Your images and project details are saved locally in this browser. No database is required.</p><label class="dropzone"><input id="design-image" type="file" accept="image/*"><strong>Click to upload a design preview</strong><div class="file-name"></div></label><div id="image-preview" class="image-preview" hidden><img src="" alt="Design preview"></div><input id="image-data" type="hidden" name="image"><div class="form-grid" style="margin-top:18px"><div class="field full"><label>Project title</label><input name="title" maxlength="120" required placeholder="e.g. Velora — Fashion storefront"></div><div class="field"><label>Category</label><select name="category"><option>Website design</option><option>E-commerce</option><option>Landing page</option><option>Dashboard</option><option>Brand website</option><option>Web app</option></select></div><div class="field"><label>Live website URL</label><input name="url" type="url" placeholder="https://example.com"></div><div class="field full"><label>Short description</label><textarea name="description" maxlength="500" required placeholder="What did you design or build?"></textarea></div><div class="field full"><label>Tags</label><input name="tags" maxlength="200" placeholder="UI/UX, Responsive, E-commerce"></div></div><div class="manager-actions"><button class="btn btn-primary" type="submit">Add to Explore Our Work ↗</button><a class="btn" href="/work">View work</a></div><div class="notice"></div><p class="manager-note">Tip: use an optimized JPG/WebP image so your browser library stays lightweight.</p></form><div class="manager-card reveal"><div style="display:flex;justify-content:space-between;gap:14px;align-items:start"><div><div class="eyebrow">Saved designs</div><h2>Your projects</h2></div><div class="manager-actions" style="margin-top:0"><button class="btn ghost-btn" type="button" data-export-work>Export</button><label class="btn ghost-btn" style="cursor:pointer">Import<input id="import-work" class="import-input" type="file" accept="application/json"></label></div></div><p class="helper">Keep a backup with Export. Import restores the same design library on another browser.</p><div id="manager-list" class="manager-list"></div></div></div></div></section>'});
}
function renderDetail(type, item) {
  const label = type==='service'?'Service':type==='solution'?'Solution':'Case study';
  const pointList = type==='service' ? item.points : ['Clearer information architecture','Premium interaction design','Responsive, performance-aware implementation','A scalable foundation for future integrations'];
  const subtitle = type==='service' ? item.description : type==='solution' ? item.description : item.description;
  return layout({title:`${item.title} — Nexora Web`,description:subtitle,current:type==='case'?'/work':type==='service'?'/services':'/solutions',canonicalPath:`/${type==='case'?'work':type+'s'}/${item.slug}`,content:`<section class="page-hero"><div class="container"><div class="eyebrow">${label}${item.category?' · '+item.category:''}</div><h1>${item.title}</h1><p>${subtitle}</p></div></section><section class="section"><div class="container split"><div class="project large reveal"><div class="project-visual ${item.tone||'violet'}"></div><div class="project-content"><div class="eyebrow">Made by Nexora Web</div><h3>${type==='service'?'A system built for clarity.':'A representative Nexora engagement.'}</h3></div></div><div class="reveal"><div class="eyebrow">What it includes</div><h2>Built around the details that make the experience work.</h2><ul class="checks">${pointList.map(p=>`<li><span class="check">✓</span><span>${p}</span></li>`).join('')}</ul></div></div></section><section class="section dark"><div class="container center reveal"><div class="eyebrow">Next step</div><h2 style="font-size:clamp(2.5rem,5vw,5rem);line-height:.98;letter-spacing:-.06em">Let’s shape your version of it.</h2><a class="btn btn-primary" href="/start-project">Start a project ↗</a></div></section>`});
}
function renderProcess(){return layout({title:'Process — Nexora Web',description:'A focused process from discovery to design, development and launch.',current:'/process',content:`<section class="page-hero"><div class="container"><div class="eyebrow">Process</div><h1>A clear path from first question to final pixel.</h1><p>We use a small number of deliberate stages so strategy, design and engineering stay connected.</p></div></section><section class="section"><div class="container">${[['01','Discover','We align on goals, audiences, offer, constraints and the real problem to solve.'],['02','Define','We shape content architecture, journeys, creative direction and measures of success.'],['03','Design','We build the visual system, responsive patterns and interaction language.'],['04','Build & launch','We implement, test, tune performance, connect integrations and prepare the experience for handoff.']].map(([n,t,p])=>`<div class="step" style="color:var(--text);border-color:var(--line)"><div class="num" style="color:var(--purple)">${n}</div><div><h3>${t}</h3><p class="muted">${p}</p></div></div>`).join('')}</div></section>`});}
function renderAbout(){return layout({title:'About Nexora Web',description:'Learn how Nexora Web approaches digital strategy, design and engineering.',current:'/about',content:`<section class="page-hero"><div class="container"><div class="eyebrow">About Nexora</div><h1>We build digital work with clarity and character.</h1><p>Nexora Web is a design-and-engineering studio for businesses that are ready to raise the standard of their digital presence.</p></div></section><section class="section"><div class="container split"><div><div class="eyebrow">Our point of view</div><h2>Good digital work should make the business easier to understand.</h2></div><div><p class="muted">We reduce noise, sharpen hierarchy and build interactions that support the story instead of competing with it.</p><p class="muted">The result is a site that feels distinctive on day one and remains useful months after launch.</p><a class="btn btn-primary" href="/contact">Talk to Nexora ↗</a></div></div></section><section class="section tight"><div class="container metrics"><div class="metric"><strong>12+</strong><span>Launches delivered</span></div><div class="metric"><strong>06</strong><span>Core capabilities</span></div><div class="metric"><strong>04</strong><span>Process stages</span></div><div class="metric"><strong>01</strong><span>Connected team</span></div></div></section>`});}
