function renderStart(){return layout({title:'Start a project — Nexora Web',description:'Send Nexora Web a structured project brief.',current:'/start-project',content:`<section class="page-hero"><div class="container"><div class="eyebrow">Project brief</div><h1>Tell us what you’re building.</h1><p>Four short steps. Enough context for a useful first response.</p></div></section><section class="section"><div class="container form-shell"><div class="reveal"><div class="eyebrow">What happens next</div><h2>We review the brief, align on the problem and come back with the clearest next step.</h2><ul class="checks"><li><span class="check">✓</span><span>Business context, goals and challenge</span></li><li><span class="check">✓</span><span>Service and budget signal</span></li><li><span class="check">✓</span><span>Timeline and constraints</span></li></ul></div><form id="project-form" class="form-card wizard reveal"><div class="wizard-bar"><strong>Project brief</strong><span class="muted" data-step-label>1 / 4</span></div><div class="progress"><span></span></div><div data-step><div class="field"><label>What are you building?</label><select name="project_type" required><option value="">Select one</option><option>Business website</option><option>E-commerce website</option><option>Digital product</option><option>Brand + website</option><option>Something else</option></select></div><button class="btn btn-primary" type="button" data-next style="margin-top:18px">Continue ↗</button></div><div data-step hidden><div class="form-grid"><div class="field"><label>Your name</label><input name="name" required maxlength="80"></div><div class="field"><label>Work email</label><input name="email" type="email" required maxlength="120"></div><div class="field full"><label>Company</label><input name="company" required maxlength="120"></div></div><div style="margin-top:18px"><button class="btn" type="button" data-prev>Back</button> <button class="btn btn-primary" type="button" data-next>Continue ↗</button></div></div><div data-step hidden><div class="form-grid"><div class="field"><label>Primary service</label><select name="service" required><option>Web Design</option><option>Development</option><option>E-commerce</option><option>UI/UX</option><option>Branding</option><option>Growth</option></select></div><div class="field"><label>Budget range</label><select name="budget" required><option>Under $2k</option><option>$2k–$5k</option><option>$5k–$10k</option><option>$10k+</option><option>Let’s discuss</option></select></div><div class="field full"><label>Target timeline</label><select name="timeline" required><option>ASAP</option><option>2–4 weeks</option><option>1–2 months</option><option>3+ months</option><option>Flexible</option></select></div></div><div style="margin-top:18px"><button class="btn" type="button" data-prev>Back</button> <button class="btn btn-primary" type="button" data-next>Continue ↗</button></div></div><div data-step hidden><div class="field"><label>Project details</label><textarea name="details" required maxlength="3000" placeholder="Goals, current site, constraints, references—anything useful."></textarea></div><div style="margin-top:18px"><button class="btn" type="button" data-prev>Back</button> <button class="btn btn-primary" type="submit">Send brief ↗</button></div><div class="notice"></div></div></form></div></section>`});}
