const FAVICON = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#5b2cff"/><path d="M17 46V18h7l16 17V18h7v28h-7L24 29v17h-7z" fill="white"/></svg>`;
const OG_IMAGE = `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630"><rect width="1200" height="630" fill="#f8f7fb"/><circle cx="995" cy="110" r="250" fill="#6b35ff" opacity=".08"/><circle cx="1020" cy="130" r="155" fill="#6b35ff" opacity=".14"/><text x="78" y="205" font-family="Arial,Helvetica,sans-serif" font-size="28" font-weight="700" fill="#5b2cff" letter-spacing="4">NEXORA WEB</text><text x="78" y="305" font-family="Arial,Helvetica,sans-serif" font-size="76" font-weight="700" fill="#17151f">Build digital.</text><text x="78" y="390" font-family="Arial,Helvetica,sans-serif" font-size="76" font-weight="700" fill="#17151f">Make it matter.</text><text x="80" y="460" font-family="Arial,Helvetica,sans-serif" font-size="26" fill="#645f70">Premium websites, product design &amp; digital systems.</text></svg>`;
const ROBOTS = `User-agent: *
Allow: /
Sitemap: /sitemap.xml
`;
const SITEMAP = `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>/</loc></url><url><loc>/services</loc></url><url><loc>/solutions</loc></url><url><loc>/work</loc></url><url><loc>/process</loc></url><url><loc>/about</loc></url><url><loc>/insights</loc></url><url><loc>/contact</loc></url><url><loc>/start-project</loc></url></urlset>`;

function pageFor(urlObj){
  const p=urlObj.pathname.replace(/\/+$/,'') || '/';
  if(p==='/') return renderHome();
  if(p==='/services') return renderListing({kind:'services',current:'/services',title:'Services — built as one connected system.',description:'From web design to development, commerce, branding and growth.'});
  if(p==='/solutions') return renderListing({kind:'solutions',current:'/solutions',title:'Solutions — designed around the business problem.',description:'Flexible digital systems for startups, growing businesses, commerce teams and enterprise.'});
  if(p==='/insights') return renderListing({kind:'insights',current:'/insights',title:'Insights — thinking behind the work.',description:'Practical ideas on conversion, systems, performance and digital craft.'});
  if(p==='/work') return renderWork();
  if(p==='/admin') return renderWorkManager();
  if(p==='/work-manager') return renderWorkManager();
  if(p==='/process') return renderProcess();
  if(p==='/about') return renderAbout();
  if(p==='/contact') return renderContact();
  if(p==='/start-project') return renderStart();
  if(p==='/privacy') return renderLegal('Privacy');
  if(p==='/terms') return renderLegal('Terms & Conditions');
  let m=p.match(/^\/services\/([a-z0-9-]+)$/); if(m){const x=services.find(s=>s.slug===m[1]); return x?renderDetail('service',x):null;}
  m=p.match(/^\/solutions\/([a-z0-9-]+)$/); if(m){const x=solutions.find(s=>s.slug===m[1]); return x?renderDetail('solution',x):null;}
  m=p.match(/^\/work\/([a-z0-9-]+)$/); if(m){const x=projects.find(s=>s.slug===m[1]); return x?renderDetail('case',x):null;}
  m=p.match(/^\/insights\/([a-z0-9-]+)$/); if(m){const x=insights.find(s=>s.slug===m[1]); return x?renderDetail('insight',x):null;}
  return null;
}



async function parseJson(request) {
  const length = Number(request.headers.get('content-length') || 0);
  if (length > 1024 * 1024) throw new Error('Payload too large');
  const raw = await request.text();
  if (!raw) return {};
  try { return JSON.parse(raw); } catch { throw new Error('Invalid JSON'); }
}

function jsonResponse(status, payload, headers = {}) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...headers }
  });
}

function securityHeaders(headers = new Headers()) {
  headers.set('x-content-type-options', 'nosniff');
  headers.set('x-frame-options', 'SAMEORIGIN');
  headers.set('referrer-policy', 'strict-origin-when-cross-origin');
  headers.set('permissions-policy', 'camera=(), microphone=(), geolocation=()');
  headers.set('content-security-policy', "default-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'; img-src 'self' data: https:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; connect-src 'self'; font-src 'self' data: https:");
  return headers;
}

async function saveLead(env, table, row) {
  if (!env.DB) return false;
  if (table === 'projects') {
    await env.DB.prepare(`INSERT INTO projects (id, created_at, project_type, name, email, company, service, budget, timeline, details) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`) 
      .bind(row.id,row.createdAt,row.project_type,row.name,row.email,row.company,row.service,row.budget,row.timeline,row.details).run();
    return true;
  }
  if (table === 'contacts') {
    await env.DB.prepare(`INSERT INTO contacts (id, created_at, name, email, company, service, message) VALUES (?, ?, ?, ?, ?, ?, ?)`)
      .bind(row.id,row.createdAt,row.name,row.email,row.company,row.service,row.message).run();
    return true;
  }
  if (table === 'subscribers') {
    await env.DB.prepare(`INSERT OR IGNORE INTO subscribers (id, created_at, email) VALUES (?, ?, ?)`)
      .bind(row.id,row.createdAt,row.email).run();
    return true;
  }
  return false;
}

function rateLimited(request) {
  // Cloudflare WAF/Rate Limiting is the recommended production control.
  // This per-isolate guard is only a lightweight application-level backstop.
  const key = request.headers.get('cf-connecting-ip') || 'unknown';
  const now = Date.now();
  const bucket = globalThis.__nexoraRate || (globalThis.__nexoraRate = new Map());
  const row = bucket.get(key) || { start: now, count: 0 };
  if (now - row.start > 60_000) { row.start = now; row.count = 0; }
  row.count += 1; bucket.set(key, row);
  return row.count > 30;
}

async function handleApi(request, env) {
  if (rateLimited(request)) return jsonResponse(429, { error: 'Too many requests. Please try again shortly.' });
  const url = new URL(request.url);
  if (request.method === 'GET' && url.pathname === '/api/health') {
    let db = 'unavailable';
    if (env.DB) { try { await env.DB.prepare('SELECT 1').first(); db = 'connected'; } catch { db = 'error'; } }
    return jsonResponse(200, { ok: true, service: 'nexora-web', db, time: new Date().toISOString() });
  }
  if (request.method !== 'POST') return jsonResponse(405, { error: 'Method not allowed' }, { allow: 'GET, POST' });
  let body; try { body = await parseJson(request); } catch (err) { return jsonResponse(400, { error: err.message }); }
  try {
    if (url.pathname === '/api/projects') {
      const row={id:crypto.randomUUID(),createdAt:new Date().toISOString(),project_type:clean(body.project_type,80),name:clean(body.name,80),email:clean(body.email,120),company:clean(body.company,120),service:clean(body.service,80),budget:clean(body.budget,80),timeline:clean(body.timeline,80),details:clean(body.details,3000)};
      if(!row.name||!isEmail(row.email)||!row.company||!row.project_type||!row.details) return jsonResponse(422,{error:'Please complete the required project fields.'});
      if(!await saveLead(env,'projects',row)) return jsonResponse(503,{error:'Project intake is temporarily unavailable. Configure the D1 database binding first.'});
      return jsonResponse(201,{ok:true,id:row.id});
    }
    if (url.pathname === '/api/contact') {
      const row={id:crypto.randomUUID(),createdAt:new Date().toISOString(),name:clean(body.name,80),email:clean(body.email,120),company:clean(body.company,120),service:clean(body.service,80),message:clean(body.message,3000)};
      if(!row.name||!isEmail(row.email)||!row.message) return jsonResponse(422,{error:'Please provide your name, a valid email and a message.'});
      if(!await saveLead(env,'contacts',row)) return jsonResponse(503,{error:'Contact intake is temporarily unavailable. Configure the D1 database binding first.'});
      return jsonResponse(201,{ok:true,id:row.id});
    }
    if (url.pathname === '/api/newsletter') {
      const email=clean(body.email,120); if(!isEmail(email)) return jsonResponse(422,{error:'Enter a valid email address.'});
      if(!await saveLead(env,'subscribers',{id:crypto.randomUUID(),createdAt:new Date().toISOString(),email})) return jsonResponse(503,{error:'Newsletter signup is temporarily unavailable. Configure the D1 database binding first.'});
      return jsonResponse(201,{ok:true});
    }
    return jsonResponse(404,{error:'API route not found'});
  } catch (err) {
    return jsonResponse(500,{error:'Internal server error'});
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === '/favicon.svg') return new Response(FAVICON,{status:200,headers:securityHeaders(new Headers({'content-type':'image/svg+xml','cache-control':'public, max-age=31536000, immutable'}))});
    if (url.pathname === '/og-image.svg') return new Response(OG_IMAGE,{status:200,headers:securityHeaders(new Headers({'content-type':'image/svg+xml','cache-control':'public, max-age=31536000, immutable'}))});
    if (url.pathname === '/robots.txt') return new Response(ROBOTS,{status:200,headers:securityHeaders(new Headers({'content-type':'text/plain; charset=utf-8','cache-control':'public, max-age=3600'}))});
    if (url.pathname === '/sitemap.xml') return new Response(SITEMAP,{status:200,headers:securityHeaders(new Headers({'content-type':'application/xml; charset=utf-8','cache-control':'public, max-age=3600'}))});
    if (url.pathname.startsWith('/api/')) {
      const response = await handleApi(request, env);
      const headers = securityHeaders(new Headers(response.headers));
      return new Response(response.body, { status: response.status, headers });
    }
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return new Response('Method Not Allowed', { status: 405, headers: securityHeaders(new Headers({ 'content-type':'text/plain; charset=utf-8' })) });
    }
    const html = pageFor(url);
    if (!html) {
      const body = layout({title:'404 — Nexora Web',description:'Page not found.',current:'',content:`<section class="page-hero"><div class="container"><div class="eyebrow">404</div><h1>That page moved.</h1><p>The page you were looking for is not here.</p><a class="btn btn-primary" href="/">Back home ↗</a></div></section>`});
      return new Response(body,{status:404,headers:securityHeaders(new Headers({'content-type':'text/html; charset=utf-8','cache-control':'no-store'}))});
    }
    return new Response(html,{status:200,headers:securityHeaders(new Headers({'content-type':'text/html; charset=utf-8','cache-control':'public, max-age=300, stale-while-revalidate=3600'}))});
  }
};